public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Check if the input graph is null
    if (graph == null) {
        throw new IllegalArgumentException("The input graph cannot be null");
    }

    // Create a new graph with the same vertices and edges as the input graph
    Graph<V,E> identityGraph = new Graph<V,E>(graph.getVertices(), graph.getEdges());

    // Create a mapping from the input graph to the identity graph
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>(graph, identityGraph);

    // Add a mapping from each vertex in the input graph to itself in the identity graph
    for (V vertex : graph.getVertices()) {
        mapping.addMapping(vertex, vertex);
    }

    return mapping;
}

