public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if the result map is null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Clear the target graph and result map
    target.clear();
    resultMap.clear();

    // Create a new bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<>();

    // Add vertices to the bipartite graph
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            V vertex = new Vertex<>(i, j);
            bipartiteGraph.addVertex(vertex);
            resultMap.put(vertex.toString(), vertex);
        }
    }

    // Add edges to the bipartite graph
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            V source = resultMap.get(i + "," + j);
            V target = resultMap.get((i + 1) % 2 + "," + j);
            E edge = new Edge<>(source, target);
            bipartiteGraph.addEdge(edge);
        }
    }

    // Set the target graph to the bipartite graph
    target = bipartiteGraph;
}

