        throw new IndexOutOfBoundsException("Offset must be non-negative and less than the length of the data");
    }
    if (len < 0 || len > b.length - off) {
        throw new IndexOutOfBoundsException("Length must be non-negative and less than the length of the data minus the offset");
    }
    if (len == 0) {
        return;
    }
    // Write the data to the output stream
    out.write(b, off, len);
}

