public final byte[] toByteArray() {
    if (bufferList.isEmpty()) {
        return new byte[0];
    }

    int totalLength = 0;
    for (ByteBuffer buffer : bufferList) {
        totalLength += buffer.remaining();
    }

    byte[] result = new byte[totalLength];
    int offset = 0;
    for (ByteBuffer buffer : bufferList) {
        int length = buffer.remaining();
        buffer.get(result, offset, length);
        offset += length;
    }

    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    sb.append('\n');
                    i++;
                } else if (nextChar == 'r') {
                    sb.append('\r');
                    i++;
                } else if (nextChar == 't') {
                    sb.append('\t');
                    i++;
                } else if (nextChar == 'b') {
                    sb.append('\b');
                    i++;
                } else if (nextChar == 'f') {
                    sb.append('\f');
                    i++;
                } else if (nextChar == '\\') {
                    sb.append('\\');
                    i++;
                } else if (nextChar == '\'') {
                    sb.append('\'');
                    i++;
                } else if (nextChar == '\"') {
                    sb.append('\"');
                    i++;
                } else {
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
                }
            } else {
                throw new Exception("Invalid escape sequence: \\");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

