final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.getConstantPoolCount()) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Check if the char buffer is large enough
    if (charBuffer.length < classFileBuffer.getConstantPoolEntry(constantPoolEntryIndex).getSize()) {
        throw new IllegalArgumentException("Char buffer is not large enough to hold the string");
    }

    // Read the string from the constant pool entry
    String string = classFileBuffer.getConstantPoolEntry(constantPoolEntryIndex).getUtf8String();

    // Copy the string to the char buffer
    string.getChars(0, string.length(), charBuffer, 0);

    return string;
}

private static char decodeHexNibble(final char c) {
    if (c >= '0' && c <= '9') {
        return (char) (c - '0');
    } else if (c >= 'a' && c <= 'f') {
        return (char) (c - 'a' + 10);
    } else if (c >= 'A' && c <= 'F') {
        return (char) (c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

