public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    if (!uri.toString().startsWith(this.pattern)) {
        return null;
    }
    String[] parts = uri.toString().split("/");
    if (parts.length != this.parts.length) {
        return null;
    }
    Map<String, String> parameters = new HashMap<>();
    for (int i = 0; i < parts.length; i++) {
        if (this.parts[i].startsWith("{") && this.parts[i].endsWith("}")) {
            parameters.put(this.parts[i].substring(1, this.parts[i].length() - 1), parts[i]);
        }
    }
    return new MatchResult(parameters);
}

