        throw new IllegalArgumentException("Dataset cannot be empty");
    }

    // Check if the dataset has the same number of columns as the bucket
    if (dataset.getColumnCount() != getColumnCount()) {
        return false;
    }

    // Check if the dataset has the same column names as the bucket
    for (int i = 0; i < dataset.getColumnCount(); i++) {
        if (!dataset.getColumnName(i).equals(getColumnName(i))) {
            return false;
        }
    }

    // Check if the dataset has the same data types as the bucket
    for (int i = 0; i < dataset.getColumnCount(); i++) {
