private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null");
    }

    if (vertices.isEmpty()) {
        return true;
    }

    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }

        for (V otherVertex : vertices) {
            if (vertex != otherVertex && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys list must not be null or empty");
    }

    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int lowerBound = key.lowerBound();
        if (lowerBound < 0) {
            throw new IllegalArgumentException("Lower bound must not be negative");
        }
        lowerBounds.add(lowerBound);
    }

    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    int numTypes = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == '(') {
            numTypes++;
        } else if (c == ')') {
            numTypes--;
        } else if (c == 'L') {
            i = descriptor.indexOf(';', i);
            if (i == -1) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    }

    if (numTypes != 0) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    for (int i = 0; i < numTypes; i++) {
