public static String applyRelativePath(String path, String relativePath) {
    // Check if the input paths are valid
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Input paths cannot be null");
    }

    // Check if the relative path is valid
    if (!relativePath.startsWith("/")) {
        throw new IllegalArgumentException("Relative path must start with '/'");
    }

    // Split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path is valid
    if (relativePathComponents.length == 0) {
        throw new IllegalArgumentException("Relative path cannot be empty");
    }

    // Split the full path into its components
    String[] fullPathComponents = path.split("/");

    // Check if the full path is valid
    if (fullPathComponents.length == 0) {
        throw new IllegalArgumentException("Full path cannot be empty");
    }

    // Remove the last component of the full path
    String[] newFullPathComponents = Arrays.copyOf(fullPathComponents, fullPathComponents.length - 1);

    // Add the relative path components to the new full path
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            // Remove the last component of the new full path
            newFullPathComponents = Arrays.copyOf(newFullPathComponents, newFullPathComponents.length - 1);
        } else {
            // Add the component to the new full path
            newFullPathComponents = Arrays.copyOf(newFullPathComponents, newFullPathComponents.length + 1);
            newFullPathComponents[newFullPathComponents.length - 1] = component;
        }
    }

    // Join the new full path components into a string
    String newFullPath = String.join("/", newFullPathComponents);

    return newFullPath;
}

