private String buildContentRange() {
    // Calculate the range start and end indices
    int rangeStart = (currentPage - 1) * itemsPerPage + 1;
    int rangeEnd = Math.min(currentPage * itemsPerPage, totalItems);

    // Build the 'Content-Range' value
    String contentRange = String.format("items %d-%d/%d", rangeStart, rangeEnd, totalItems);

    return contentRange;
}

